#!/usr/bin/env python3
"""Task-scoped helper: construct and validate one calendar event artifact for
the requested Team Meeting (next Wednesday, 3:00-4:00 PM local time).

The helper only computes the target date/time, renders a single VEVENT in
iCalendar text, validates that rendered artifact, and prints it to stdout.
"""

import datetime as dt
import os
import sys
import uuid

WEDNESDAY = 2  # datetime.weekday(): Monday == 0 ... Wednesday == 2


def next_wednesday_after(today):
    days_ahead = (WEDNESDAY - today.weekday()) % 7
    if days_ahead == 0:
        days_ahead = 7  # today is Wednesday -> next week's Wednesday
    return today + dt.timedelta(days=days_ahead)


def local_tz_name():
    """Best-effort IANA-style local timezone name (no network access)."""
    tz = os.environ.get("TZ")
    if tz and "/" in tz:
        return tz
    try:
        with open("/etc/timezone", "r", encoding="utf-8") as fh:
            name = fh.read().strip()
        if "/" in name:
            return name
    except OSError:
        pass
    try:
        real = os.path.realpath("/etc/localtime")
        prefix = "/usr/share/zoneinfo/"
        if real.startswith(prefix):
            return real[len(prefix):]
    except OSError:
        pass
    return None


def local_offset_now():
    return dt.datetime.now().astimezone().utcoffset() or dt.timedelta(0)


def fmt_utc(value):
    return value.astimezone(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")


def fmt_local(value):
    return value.strftime("%Y%m%dT%H%M%S")


def ical_escape(value):
    return (value.replace("\\", "\\\\")
                 .replace(";", "\\;")
                 .replace(",", "\\,")
                 .replace("\n", "\\n"))


def fold_line(line):
    """Fold content lines longer than 75 octets per RFC 5545 (ASCII here)."""
    data = line.encode("utf-8")
    if len(data) <= 75:
        return [line]
    chunks = []
    pos = 0
    first = True
    while pos < len(data):
        end = min(pos + 75, len(data))
        if first:
            chunks.append(data[pos:end].decode("utf-8"))
            first = False
        else:
            chunks.append(" " + data[pos:end].decode("utf-8"))
        pos = end
    return chunks


def main():
    now_local = dt.datetime.now().astimezone()
    meeting_date = next_wednesday_after(now_local.date())
    start_local = dt.datetime(meeting_date.year, meeting_date.month,
                              meeting_date.day, 15, 0)
    end_local = start_local + dt.timedelta(hours=1)

    tz_name = local_tz_name()
    if tz_name:
        start_line = "DTSTART;TZID=%s:%s" % (tz_name, fmt_local(start_local))
        end_line = "DTEND;TZID=%s:%s" % (tz_name, fmt_local(end_local))
        tz_display = tz_name
    else:
        offset = local_offset_now()
        start_line = "DTSTART:%s" % fmt_utc(start_local - offset)
        end_line = "DTEND:%s" % fmt_utc(end_local - offset)
        tz_display = "UTC (offset %s)" % offset

    uid = "%s@team-meeting-calendar.local" % uuid.uuid4()
    stamp = fmt_utc(dt.datetime.now(dt.timezone.utc))

    summary = "Team Meeting"
    description = ical_escape(
        "Team meeting on %s at 3:00 PM for one hour (%s)."
        % (meeting_date.strftime("%B %-d, %Y"), tz_display))

    lines = [
        "BEGIN:VCALENDAR",
        "VERSION:2.0",
        "PRODID:-//Team Meeting Helper//Calendar Skill//EN",
        "CALSCALE:GREGORIAN",
        "BEGIN:VEVENT",
        "UID:%s" % uid,
        "DTSTAMP:%s" % stamp,
        start_line,
        end_line,
        "SUMMARY:%s" % summary,
        "DESCRIPTION:%s" % description,
        "STATUS:CONFIRMED",
        "TRANSP:OPAQUE",
        "SEQUENCE:0",
        "END:VEVENT",
        "END:VCALENDAR",
    ]

    folded = []
    for line in lines:
        folded.extend(fold_line(line))
    ics_text = "\n".join(folded) + "\n"

    print("meeting_date=%s" % meeting_date.isoformat())
    print("start_local=%s" % start_local.isoformat())
    print("end_local=%s" % end_local.isoformat())
    print("timezone=%s" % tz_display)
    print("ICS_BEGIN")
    sys.stdout.write(ics_text)
    print("ICS_END")

    # --- Validate the rendered artifact ---
    problems = []
    if meeting_date.weekday() != WEDNESDAY:
        problems.append("meeting date is not a Wednesday")
    if start_local.hour != 15 or start_local.minute != 0:
        problems.append("start is not 3:00 PM")
    if (end_local - start_local) != dt.timedelta(hours=1):
        problems.append("duration is not one hour")
    for token in ("BEGIN:VCALENDAR", "VERSION:2.0", "CALSCALE:GREGORIAN",
                  "BEGIN:VEVENT", "UID:", "DTSTAMP:", "DTSTART",
                  "DTEND", "SUMMARY:Team Meeting", "DESCRIPTION:",
                  "STATUS:CONFIRMED", "END:VEVENT", "END:VCALENDAR"):
        if token not in ics_text:
            problems.append("missing %r" % token)
    for line in folded:
        if len(line.encode("utf-8")) > 76:
            problems.append("content line too long: %r" % line[:60])
    start_token = start_line.split(":", 1)[1].strip()
    end_token = end_line.split(":", 1)[1].strip()
    try:
        if len(start_token) == 15 and start_token.endswith("Z"):
            start_parsed = dt.datetime.strptime(start_token,
                                                "%Y%m%dT%H%M%SZ").replace(
                                                    tzinfo=dt.timezone.utc)
        else:
            start_parsed = dt.datetime.strptime(start_token, "%Y%m%dT%H%M%S")
        if len(end_token) == 15 and end_token.endswith("Z"):
            end_parsed = dt.datetime.strptime(end_token,
                                              "%Y%m%dT%H%M%SZ").replace(
                                                  tzinfo=dt.timezone.utc)
        else:
            end_parsed = dt.datetime.strptime(end_token, "%Y%m%dT%H%M%S")
        if not (end_parsed > start_parsed):
            problems.append("end is not after start")
    except ValueError as exc:
        problems.append("could not parse DTSTART/DTEND: %s" % exc)

    if problems:
        print("VALIDATION_FAILED")
        for p in problems:
            print("- %s" % p)
        return 1
    print("VALIDATION_OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Task-scoped helper for the requested "Team Meeting" calendar event.

Compute the date/time for "next Wednesday at 3 PM, lasting one hour" on this
host, and (optionally) validate the final .ics artifact produced for it.
Only this one event is handled; no other calendar data is touched.
"""

import datetime as dt
import json
import os
import sys

MEETING_ICS = os.path.join(os.path.dirname(os.path.abspath(__file__)), "team_meeting.ics")


def iana_timezone():
    """Best-effort IANA timezone name for this host."""
    try:
        with open("/etc/timezone", "r", encoding="utf-8") as fh:
            zone = fh.read().strip()
            if zone and "/" in zone:
                return zone
    except OSError:
        pass
    try:
        link = os.readlink("/etc/localtime")
        if "zoneinfo" in link:
            return link.split("zoneinfo/", 1)[1]
    except OSError:
        pass
    return None


def compute_values():
    """Next Wednesday strictly after today, at 15:00 local for one hour."""
    today = dt.date.today()
    # weekday(): Mon=0 ... Sun=6 ; Wednesday = 2
    days_ahead = (2 - today.weekday()) % 7
    if days_ahead == 0:  # today is Wednesday -> next Wednesday is one week out
        days_ahead = 7
    meeting_date = today + dt.timedelta(days=days_ahead)
    start_local = dt.datetime(meeting_date.year, meeting_date.month, meeting_date.day, 15, 0, 0)
    end_local = start_local + dt.timedelta(hours=1)
    return {
        "today": today.isoformat(),
        "next_wednesday": meeting_date.isoformat(),
        "weekday_name": meeting_date.strftime("%A"),
        "start_local": start_local.isoformat(),
        "end_local": end_local.isoformat(),
        "iana_tz": iana_timezone(),
        "dtstamp": dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ"),
        "uid": "team-meeting-%s@example.com" % meeting_date.strftime("%Y%m%d"),
    }


def validate():
    """Validate the team_meeting.ics artifact produced for this event."""
    if not os.path.exists(MEETING_ICS):
        print("MISSING: %s" % MEETING_ICS)
        sys.exit(1)
    with open(MEETING_ICS, "r", encoding="utf-8") as fh:
        text = fh.read()
    errors = []
    for token in ("BEGIN:VCALENDAR", "VERSION:2.0", "PRODID", "CALSCALE:GREGORIAN",
                  "BEGIN:VEVENT", "UID:", "DTSTAMP:", "DTSTART", "DTEND",
                  "SUMMARY:Team Meeting", "END:VEVENT", "END:VCALENDAR"):
        if token not in text:
            errors.append("missing token: %s" % token)

    def field(name):
        for line in text.splitlines():
            if line.startswith(name + ":"):
                return line.split(":", 1)[1]
            if line.startswith(name + ";"):
                return line.split(":", 1)[1]
        return None

    try:
        # TZID=America/New_York:20250129T150000  OR  20250129T150000Z
        raw_start = field("DTSTART").split(":", 1)[1]
        raw_end = field("DTEND").split(":", 1)[1]
        if raw_start.endswith("Z"):
            start_dt = dt.datetime.strptime(raw_start, "%Y%m%dT%H%M%SZ").replace(tzinfo=dt.timezone.utc)
        else:
            start_dt = dt.datetime.strptime(raw_start, "%Y%m%dT%H%M%S")
        if raw_end.endswith("Z"):
            end_dt = dt.datetime.strptime(raw_end, "%Y%m%dT%H%M%SZ").replace(tzinfo=dt.timezone.utc)
        else:
            end_dt = dt.datetime.strptime(raw_end, "%Y%m%dT%H%M%S")
        if start_dt.weekday() != 2:  # Wednesday
            errors.append("DTSTART is not a Wednesday: %s" % raw_start)
        if (start_dt.hour, start_dt.minute) != (15, 0):
            errors.append("DTSTART is not 3:00 PM: %s" % raw_start)
        if (end_dt - start_dt) != dt.timedelta(hours=1):
            errors.append("DTEND - DTSTART is not exactly 1 hour")
    except Exception as exc:  # noqa: BLE001 - report any parse problem
        errors.append("date parse error: %r" % exc)

    if errors:
        print("INVALID:")
        for err in errors:
            print("  - " + err)
        sys.exit(1)
    print("VALID: %s is a Wednesday, 3:00 PM - 4:00 PM, one hour." % field("DTSTART").split(":", 1)[1])


if __name__ == "__main__":
    mode = sys.argv[1] if len(sys.argv) > 1 else "compute"
    if mode == "validate":
        validate()
    else:
        print(json.dumps(compute_values(), indent=2))
